import numpy as np
img = Image.open('mol_0248.png').convert('L')
bw = np.array(img) < 128

def hwidth(y, xc, half=60):
    xs = [x for x in range(xc-half, xc+half) if 0<=x<bw.shape[1] and bw[y,x]]
    return (min(xs), max(xs), max(xs)-min(xs)) if xs else None

def scan_perp(p, q, t, half=50):
    p = np.array(p,float); q = np.array(q,float)
    d = q-p; L=np.hypot(*d); d/=L; n=np.array([-d[1],d[0]])
    c = p + t*(q-p)
    ink=[]
    for s in np.arange(-half,half,0.5):
        pt=c+s*n; x,y=int(round(pt[0])),int(round(pt[1]))
