from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np

def det_at(xyz, c, n1, n2, n3):
    cc = xyz[c]
    us = []
    for n in (n1,n2,n3):
        v = xyz[n]-cc; us.append(v/np.linalg.norm(v))
    hdir = -sum(us); hdir/=np.linalg.norm(hdir)
    pH = cc + hdir
    M = np.array([xyz[n1]-pH, xyz[n2]-pH, xyz[n3]-pH])
    return np.linalg.det(M)

# get CIP priority order (high->low) for centers 3,6,8 from a built molecule
mol0 = Chem.MolFromSmiles("CCC[C@H]1C=C[C@H](C)[C@H](C)CC1")
Chem.AssignStereochemistry(mol0, cleanIt=True, force=True)
prio={}
for c in (3,6,8):
    a = mol0.GetAtomWithIdx(c)
    pr = {n.GetIdx(): int(n.GetProp('_CIPRank')) for n in a.GetNeighbors()}
    order_hi_lo = sorted(pr, key=lambda k:-pr[k])  # higher rank = higher priority
    prio[c]=order_hi_lo
    print(f"center {c}: _CIPRank={pr} -> priority hi->lo: {order_hi_lo}")

def get_xyz(sml, seed=2):
    mol = Chem.AddHs(Chem.MolFromSmiles(sml))
    ps=AllChem.ETKDGv3(); ps.randomSeed=seed; ps.numThreads=1
    AllChem.EmbedMolecule(mol, ps); AllChem.MMFFOptimizeMolecule(mol, maxIters=300)
    conf=mol.GetConformer()
    return {i: np.array([conf.GetAtomPosition(i).x,conf.GetAtomPosition(i).y,conf.GetAtomPosition(i).z]) for i in range(12)}

# calibrate det sign -> CIP for each center using (3R,6R,8R) and (3S,6S,8S)
cal={}
for label,cips in [("(3R,6R,8R)",{3:'R',6:'R',8:'R'}), ("(3S,6S,8S)",{3:'S',6:'S',8:'S'})]:
    xyz = get_xyz(sml={"(3R,6R,8R)":"CCC[C@H]1C=C[C@H](C)[C@H](C)CC1",
                       "(3S,6S,8S)":"CCC[C@@H]1C=C[C@@H](C)[C@@H](C)CC1"}[label])
    for c in (3,6,8):
        n1,n2,n3 = prio[c]
        d = det_at(xyz,c,n1,n2,n3)
        cal.setdefault(c,{})[cips[c]]=np.sign(d)
print("calibration (CIP -> det sign):", cal)

# depiction model: flat ring + propyl front + methyls back (several z variants)
def read_config(data):
    order=sorted(data); scale=1.54/350.0
    xyz={i: np.array([data[i][0]*scale,-data[i][1]*scale,data[i][2]]) for i in order}
    res={}
    for c in (3,6,8):
        n1,n2,n3 = prio[c]
        d = det_at(xyz,c,n1,n2,n3)
        res[c]=d
    return res

variants = {
 "flat, propyl+1.5, Me-1.5": {0:(365,505,1.2),1:(260,520,1.2),2:(45,860,1.5),3:(423,742,0.0),4:(433,385,0.0),5:(615,55,0.0),6:(612,177,0.0),7:(677,112,-1.5),8:(608,437,0.0),9:(500,474,-1.5),10:(960,535,0.0),11:(787,940,0.0)},
 "pucker A": {0:(365,505,1.2),1:(260,520,1.2),2:(45,860,1.5),3:(423,742,1.0),4:(433,385,0.5),5:(615,55,0.7),6:(612,177,0.3),7:(677,112,-1.2),8:(608,437,-0.3),9:(500,474,-1.2),10:(960,535,-0.7),11:(787,940,0.7)},
 "pucker B": {0:(365,505,1.4),1:(260,520,1.3),2:(45,860,2.0),3:(423,742,1.2),4:(433,385,0.4),5:(615,55,0.6),6:(612,177,0.2),7:(677,112,-1.6),8:(608,437,-0.5),9:(500,474,-1.6),10:(960,535,-0.9),11:(787,940,0.9)},
}
for label,data in variants.items():
    d = read_config(data)
    def cip(c):
        s = np.sign(d[c])
        return 'S' if s==cal[c]['S'] else 'R'
    print(f"{label:32s} det3={d[3]:+8.3f} det6={d[6]:+8.3f} det8={d[8]:+8.3f} -> CIPs: 3:{cip(3)} 6:{cip(6)} 8:{cip(8)}")
